    stem=os.path.splitext(os.path.basename(f))[0]
    txt=open(f,encoding="utf-8").read()
    m=re.match(r"^---\n(.*?)\n---\n",txt,re.S)
    if not m: problems.append(f"{stem}: no frontmatter"); continue
    try: fm=yaml.safe_load(m.group(1))
    except Exception as e: problems.append(f"{stem}: YAML ERROR {e}"); continue
    names.add(fm.get("name"))
    if fm.get("name")!=stem: problems.append(f"{stem}: name mismatch '{fm.get('name')}'")
    if not fm.get("description"): problems.append(f"{stem}: no description")
    if fm.get("model") not in VALID_MODELS: problems.append(f"{stem}: bad model '{fm.get('model')}'")
    tools=fm.get("tools") or []
    if isinstance(tools,str): tools=[t.strip() for t in tools.split(",")]
    bad=[t for t in tools if t not in VALID_TOOLS]
    if bad: problems.append(f"{stem}: bad tools {bad}")
